class Vault extends Table {
  TextColumn get id => text()();
  TextColumn get mode => text()(); // 'local_only', 'google_enabled'
  IntColumn get createdAtMs => integer()();
  IntColumn get vmkWrapVersion => integer()(); // for key rotation
  IntColumn get activeEncryptionVersion => integer()(); // AES-256-GCM or future

  @override
  Set<Column> get primaryKey => {id};
}

