@DataClassName('VaultThumbnail')
class Thumbnails extends Table {
  TextColumn get id => text()();
  TextColumn get photoId => text()();
  TextColumn get encryptedPath => text()();
  TextColumn get nonce => text()();
  IntColumn get encryptionVersion => integer()();
  IntColumn get width => integer()();
  IntColumn get height => integer()();
  TextColumn get checksumSha256 => text()();

  @override
  Set<Column> get primaryKey => {id};
}

