class ShareExports extends Table {
  TextColumn get id => text()();
  TextColumn get photoId => text().nullable()();
  TextColumn get exportMode => text()(); // 'encrypted', 'decrypted'
  TextColumn get packagePath => text()();
  IntColumn get expiresAtMs => integer().nullable()();
  IntColumn get createdAtMs => integer()();

  @override
  Set<Column> get primaryKey => {id};
}

