  IntColumn get movedAtMs => integer()();
  IntColumn get expiresAtMs => integer()(); // Unix timestamp for auto-delete
  IntColumn get syncDeletePending =>
      integer().withDefault(const Constant(0))(); // 0 or 1

  @override
