  TextColumn get id => text()();
  TextColumn get eventType =>
      text()(); // 'unlock', 'lock', 'export', 'restore', etc.
  TextColumn get severity => text()(); // 'info', 'warning', 'critical'
  IntColumn get occurredAtMs => integer()();
